\href{https://stacks.math.columbia.edu/tag/0AJQ}{\texttt{Stacks tag 0AJQ}}


\begin{reference}
\cite[Proposition 7.5.5]{EGA1}
\end{reference}
Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal. Then
\begin{enumerate}
\item every object of the category $\mathcal{C}'$
(\ref{equation-C-prime}) is Noetherian,
\item if $B \in \Ob(\mathcal{C}')$ and $J \subset B$ is an ideal,
then $B/J$ is an object of $\mathcal{C}'$,
\item for a finite type $A$-algebra $C$ the $I$-adic completion
$C^\wedge$ is in $\mathcal{C}'$,
\item in particular the completion $A[x_1, \ldots, x_r]^\wedge$
is in $\mathcal{C}'$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0AJS}{\texttt{Stacks tag 0AJS}}


Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal.
Let $B$ be an object of (\ref{equation-C-prime}). Then
\begin{enumerate}
\item the pro-objects
$\{\NL_{B/A}^\wedge \otimes_B B/I^nB\}$ and $\{\NL_{B_n/A_n}\}$
of $D(B)$ are strictly isomorphic (see proof for elucidation),
\item $\NL_{B/A}^\wedge = R\lim \NL_{B_n/A_n}$ in $D(B)$.
\end{enumerate}
Here $B_n$ and $A_n$ are as in Section \ref{restricted-section-two-categories}.

\href{https://stacks.math.columbia.edu/tag/0AQJ}{\texttt{Stacks tag 0AQJ}}



With assumptions as in Lemma \ref{restricted-lemma-exact-sequence-NL}
assume that $B/I^nB \to C/I^nC$ is a local complete intersection
homomorphism for all $n$. Then
$H^{-1}(\NL_{B/A}^\wedge \otimes_B C) \to H^{-1}(\NL_{C/A}^\wedge)$
is injective.

\href{https://stacks.math.columbia.edu/tag/0GAK}{\texttt{Stacks tag 0GAK}}


Let $A$ be a Noetherian ring and let $I$ be an ideal.
Let $B$ be a finite type $A$-algebra.
\begin{enumerate}
\item If $\Spec(B) \to \Spec(A)$ is smooth over $\Spec(A) \setminus V(I)$,
then $B^\wedge$ is rig-smooth over $(A, I)$.
\item If $B^\wedge$ is rig-smooth over $(A, I)$,
then there exists $g \in 1 + IB$ such that $\Spec(B_g)$ is smooth
over $\Spec(A) \setminus V(I)$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0GAV}{\texttt{Stacks tag 0GAV}}


Let $A$ be a ring. Let $f_1, \ldots, f_m \in A[x_1, \ldots, x_n]$
and set $B = A[x_1, \ldots, x_n]/(f_1, \ldots, f_m)$. Assume $m \leq n$
and set $g = \det_{1 \leq i, j \leq m}(\partial f_j/\partial x_i)$.
Then
\begin{enumerate}
\item $g$ annihilates $\Ext^1_B(\NL_{B/A}, N)$ for every $B$-module $N$,
\item if $n = m$, then multiplication by $g$ on $\NL_{B/A}$ is $0$ in $D(B)$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0ALS}{\texttt{Stacks tag 0ALS}}


\begin{reference}
The rig-\'etale case of \cite[III Theorem 7]{Elkik}
\end{reference}
Let $A$ be a Noetherian ring and $I = (a)$ a principal ideal.
Let $B$ be an object of (\ref{equation-C-prime}) which is
rig-\'etale over $(A, I)$.
Then there exists a finite type $A$-algebra $C$ and an
isomorphism $B \cong C^\wedge$.

\href{https://stacks.math.columbia.edu/tag/0GG6}{\texttt{Stacks tag 0GG6}}



Let $\varphi : A \to B$ be an arrow of $\textit{WAdm}^{Noeth}$.
If $\varphi$ is adic the following are equivalent
\begin{enumerate}
\item $\varphi$ satisfies the condition defined in
Lemma \ref{restricted-lemma-finite-type-red} and
\item $\varphi$ satisfies the condition defined in
Lemma \ref{restricted-lemma-finite-type}.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0GCA}{\texttt{Stacks tag 0GCA}}



Denote $P$ the property of arrows of $\textit{WAdm}^{Noeth}$
defined in Lemma \ref{restricted-lemma-flat-axioms}.
Denote $Q$ the property defined in Lemma \ref{restricted-lemma-finite-type-red}
viewed as a property of arrows of $\textit{WAdm}^{Noeth}$.
Denote $R$ the property defined in Lemma \ref{restricted-lemma-finite-type}
viewed as a property of arrows of $\textit{WAdm}^{Noeth}$. Then
\begin{enumerate}
\item $P$ is stable under base change by $Q$
(Formal Spaces, Remark
\ref{formal-spaces-remark-base-change-variant-variant-Noetherian}), and
\item $P + R$ is stable under base change
(Formal Spaces, Remark
\ref{formal-spaces-remark-base-change-variant-Noetherian}).
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0GCE}{\texttt{Stacks tag 0GCE}}


Let $S$ be a scheme. Let $f : X \to Y$ and $g : Z \to Y$
be morphisms of locally Noetherian formal algebraic spaces over $S$.
\begin{enumerate}
\item If $f$ is flat and $g_{red} : Z_{red} \to Y_{red}$ is
locally of finite type, then the base change
$X \times_Y Z \to Z$ is flat.
\item If $f$ is flat and locally of finite type, then
the base change $X \times_Y Z \to Z$ is flat and locally of finite type.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0GGE}{\texttt{Stacks tag 0GGE}}


Let $A$ be an adic topological ring which has a finitely generated ideal
of definition. Let $f \in A$. The {\it completed principal localization}
$A_{\{f\}}$ of $A$ is the completion of $A_f = A[1/f]$
of the principal localization of $A$ at $f$ with respect to any
ideal of definition of $A$.

\href{https://stacks.math.columbia.edu/tag/0GGG}{\texttt{Stacks tag 0GGG}}



Let $\varphi : A \to B$ be an arrow of $\textit{WAdm}^{Noeth}$
which is adic and topologically of finite type.
Let $\mathfrak q \subset B$ be rig-closed.
There exists an $f \in A$ which maps to a unit in
$B/\mathfrak q$ such that we obtain a diagram
$$
\vcenter{
\begin{array}{cc}B \longrightarrow & B_{\{f\}} \\ A \longrightarrow\underset{\varphi}{\uparrow} & A_{\{f\}} \underset{\varphi_{\{f\}}}{\uparrow}\end{array}
}
\quad\text{with primes}\quad
\vcenter{
\begin{array}{ccc}\mathfrak q \longrightarrow\downarrow & \mathfrak q' \downarrow\xlongequal{} & \mathfrak q B_{\{f\}} \\ \mathfrak p \longrightarrow & \mathfrak p' & \end{array}
}
$$
such that $\mathfrak p'$ is rig-closed, i.e.,
the map $A_{\{f\}} \to B_{\{f\}}$ and the prime ideals
$\mathfrak q'$ and $\mathfrak p'$ satisfy
the equivalent conditions of Lemma \ref{restricted-lemma-rig-closed-point-relative}.

\href{https://stacks.math.columbia.edu/tag/0AQN}{\texttt{Stacks tag 0AQN}}


A rig-\'etale morphism of locally Noetherian formal algebraic spaces
is locally of finite type.

\href{https://stacks.math.columbia.edu/tag/0GD0}{\texttt{Stacks tag 0GD0}}


A rig-\'etale morphism of locally Noetherian formal algebraic spaces
is rig-smooth.

\href{https://stacks.math.columbia.edu/tag/0AQY}{\texttt{Stacks tag 0AQY}}


Let $A$ be a Noetherian ring complete with respect to an ideal $I$.
Let $B$ be an $I$-adically complete $A$-algebra. Assume that
\begin{enumerate}
\item the $I$-torsion in $A$ is $0$,
\item $A/I^n \to B/I^nB$ is flat and of finite type for all $n$.
\end{enumerate}
Then $\text{Spf}(B) \to \text{Spf}(A)$ is rig-surjective if and only
if $A/I \to B/IB$ is faithfully flat.

\href{https://stacks.math.columbia.edu/tag/0GH6}{\texttt{Stacks tag 0GH6}}


Let $S$ be a scheme. Let $f : X \to Y$ and $g : Y \to Z$
be morphisms of locally Noetherian formal algebraic spaces over $S$.
Assume
\begin{enumerate}
\item $g$ is locally of finite type,
\item $f$ is rig-smooth (resp.\ rig-\'etale) and rig-surjective,
\item $g \circ f$ is rig-smooth (resp.\ rig-\'etale)
\end{enumerate}
then $g$ is rig-smooth (resp.\ rig-\'etale).

\href{https://stacks.math.columbia.edu/tag/0AQ9}{\texttt{Stacks tag 0AQ9}}


In the situation above. If $f$ is locally of finite type, then
$f_{/T}$ is locally of finite type.

\href{https://stacks.math.columbia.edu/tag/0GDC}{\texttt{Stacks tag 0GDC}}


In the situation above. If $f$ is a closed immersion, then
$f_{/T}$ is a closed immersion.

\href{https://stacks.math.columbia.edu/tag/0GDE}{\texttt{Stacks tag 0GDE}}


In the situation above. If $f$ is quasi-compact, then
$f_{/T}$ is quasi-compact.

\href{https://stacks.math.columbia.edu/tag/0GDG}{\texttt{Stacks tag 0GDG}}


In the situation above. If $f$ is (quasi-)separated, then
$f_{/T}$ is too.

\href{https://stacks.math.columbia.edu/tag/0AQW}{\texttt{Stacks tag 0AQW}}


In the situation above. If $X$ is locally Noetherian,
$f$ is proper, and $U' \to U$ is surjective, then $f_{/T}$ is rig-surjective.

\href{https://stacks.math.columbia.edu/tag/0ARA}{\texttt{Stacks tag 0ARA}}


In the situation above. Assume $X$ is affine. Then the functor
(\ref{equation-completion-functor}) is an equivalence.

\href{https://stacks.math.columbia.edu/tag/0ARB}{\texttt{Stacks tag 0ARB}}


Let $S$ be a scheme. Let $X$ be a locally Noetherian algebraic space over $S$.
Let $T \subset |X|$ be a closed subset. Let $U \subset X$ be the open subspace
with $|U| = |X| \setminus T$. The completion functor
(\ref{equation-completion-functor})
$$
\left\{
\begin{matrix}
\text{morphisms of algebraic spaces}\\
f : X' \to X\text{ which are locally}\\
\text{of finite type and such that}\\
f^{-1}U \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
\text{morphisms }g : W \to X_{/T}\\
\text{of formal algebraic spaces}\\
\text{with }W\text{ locally Noetherian}\\
\text{and }g\text{ rig-\'etale}
\end{matrix}
\right\}
$$
sending $f : X' \to X$ to $f_{/T} : X'_{/T'} \to X_{/T}$ is an equivalence.

\href{https://stacks.math.columbia.edu/tag/0ARU}{\texttt{Stacks tag 0ARU}}



With assumptions and notation as in Theorem \ref{restricted-theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is quasi-compact if and only if $g$ is quasi-compact.

\href{https://stacks.math.columbia.edu/tag/0ARV}{\texttt{Stacks tag 0ARV}}



With assumptions and notation as in Theorem \ref{restricted-theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is quasi-separated if and only if $g$ is so.

\href{https://stacks.math.columbia.edu/tag/0ARW}{\texttt{Stacks tag 0ARW}}



With assumptions and notation as in Theorem \ref{restricted-theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is separated $\Leftrightarrow$ $g$ is
separated and $\Delta_g : W \to W \times_{X_{/T}} W$ is rig-surjective.

\href{https://stacks.math.columbia.edu/tag/0ARX}{\texttt{Stacks tag 0ARX}}



With assumptions and notation as in Theorem \ref{restricted-theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is proper if and only if $g$ is a formal modification
(Definition \ref{restricted-definition-formal-modification}).

\href{https://stacks.math.columbia.edu/tag/0GI4}{\texttt{Stacks tag 0GI4}}



With assumptions and notation as in Theorem \ref{restricted-theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is \'etale if and only if $g$ is \'etale.

\href{https://stacks.math.columbia.edu/tag/0EE2}{\texttt{Stacks tag 0EE2}}


Let $S$ be a scheme and let $X$ be an algebraic space over $S$.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Let $x \in |X|$. Let $d \in \{0, 1, 2, \ldots, \infty\}$.
We say {\it $\mathcal{F}$ has length $d$ at $x$}
if the equivalent conditions of Lemma \ref{spaces-chow-lemma-length}
are satisfied.

\href{https://stacks.math.columbia.edu/tag/0EE3}{\texttt{Stacks tag 0EE3}}


Let $S$ be a scheme. Let $i : Y \to X$ be a closed immersion of
algebraic spaces over $S$. Let $\mathcal{G}$ be a quasi-coherent
$\mathcal{O}_Y$-module. Let $y \in |Y|$ with image $x \in |X|$.
Let $d \in \{0, 1, 2, \ldots, \infty\}$. The following are
equivalent
\begin{enumerate}
\item $\mathcal{G}$ has length $d$ at $y$, and
\item $i_*\mathcal{G}$ has length $d$ at $x$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0EE8}{\texttt{Stacks tag 0EE8}}


In Situation \ref{spaces-chow-situation-setup} let $X/B$ be good.
Let $Y \subset X$ be a closed subspace. By
Remarks \ref{spaces-chow-remark-sober} and \ref{spaces-chow-remark-integral}
there are $1$-to-$1$ correspondences between
\begin{enumerate}
\item irreducible components $T$ of $|Y|$,
\item generic points of irreducible components of $|Y|$, and
\item integral closed subspaces $Z \subset Y$ with the property that
$|Z|$ is an irreducible component of $|Y|$.
\end{enumerate}
In this chapter we will call $Z$ as in (3) an
{\it irreducible component of $Y$}
and we will call $\xi \in |Z|$ its {\it generic point}.

\href{https://stacks.math.columbia.edu/tag/0EPZ}{\texttt{Stacks tag 0EPZ}}


In Situation \ref{spaces-chow-situation-setup} let $X/B$ be good. Assume $X$ is
integral.
\begin{enumerate}
\item If $Z \subset X$ is an integral closed subspace, then
the following are equivalent:
\begin{enumerate}
\item $Z$ is a prime divisor,
\item $|Z|$ has codimension $1$ in $|X|$, and
\item $\dim_\delta(Z) = \dim_\delta(X) - 1$.
\end{enumerate}
\item If $Z$ is an irreducible component of an effective Cartier
divisor on $X$, then $\dim_\delta(Z) = \dim_\delta(X) - 1$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0EQL}{\texttt{Stacks tag 0EQL}}


In Situation \ref{spaces-chow-situation-setup} let $Y/B$ be good.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_Y$-module.
Let $s \in \Gamma(Y, \mathcal{L})$ be a regular section and
assume $\dim_\delta(Y) \leq k + 1$.
Write $[Y]_{k + 1} = \sum n_i[Y_i]$ where $Y_i \subset Y$ are the
irreducible components of $Y$ of $\delta$-dimension $k + 1$.
Set $s_i = s|_{Y_i} \in \Gamma(Y_i, \mathcal{L}|_{Y_i})$. Then
\begin{equation}
\label{equation-equal-as-cycles}
[Z(s)]_k =  \sum n_i[Z(s_i)]_k
\end{equation}
as $k$-cycles on $Y$.

\href{https://stacks.math.columbia.edu/tag/0ERJ}{\texttt{Stacks tag 0ERJ}}


\begin{reference}
Similar to \cite[Definition 17.1]{F}
\end{reference}
In Situation \ref{spaces-chow-situation-setup} let $f : X \to Y$ be a morphism of
good algebraic spaces over $B$. Let $p \in \mathbf{Z}$.
A {\it bivariant class $c$ of degree $p$ for $f$} is given by a rule
which assigns to every morphism $Y' \to Y$ of good algebraic spaces over $B$
and every $k$ a map
$$
c \cap - : \CH_k(Y') \longrightarrow \CH_{k - p}(X')
$$
where $X' = Y' \times_Y X$, satisfying the following conditions
\begin{enumerate}
\item if $Y'' \to Y'$ is a proper morphism, then
$c \cap (Y'' \to Y')_*\alpha'' = (X'' \to X')_*(c \cap \alpha'')$
for all $\alpha''$ on $Y''$,
\item if $Y'' \to Y'$ a morphism of good algebraic spaces over $B$
which is flat of relative dimension $r$, then
$c \cap (Y'' \to Y')^*\alpha' = (X'' \to X')^*(c \cap \alpha')$
for all $\alpha'$ on $Y'$,
\item if $(\mathcal{L}', s', i' : D' \to Y')$ is as in
Definition \ref{spaces-chow-definition-gysin-homomorphism}
with pullback $(\mathcal{N}', t', j' : E' \to X')$ to $X'$,
then we have $c \cap (i')^*\alpha' = (j')^*(c \cap \alpha')$
for all $\alpha'$ on $Y'$.
\end{enumerate}
The collection of all bivariant classes of degree $p$ for $f$ is
denoted $A^p(X \to Y)$.

\href{https://stacks.math.columbia.edu/tag/0ERK}{\texttt{Stacks tag 0ERK}}


In Situation \ref{spaces-chow-situation-setup} let $X/B$ be good. The {\it Chow cohomology}
of $X$ is the graded $\mathbf{Z}$-algebra $A^*(X)$ whose degree
$p$ component is $A^p(X \to X)$.

\href{https://stacks.math.columbia.edu/tag/0ES0}{\texttt{Stacks tag 0ES0}}


In Situation \ref{spaces-chow-situation-setup} let $X/B$ be good.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
The first Chern class of $\mathcal{L}$ on $X$ of
Definition \ref{spaces-chow-definition-chern-classes}
is equal to the bivariant class of Lemma \ref{spaces-chow-lemma-cap-c1-bivariant}.

\href{https://stacks.math.columbia.edu/tag/0ES4}{\texttt{Stacks tag 0ES4}}


In Situation \ref{spaces-chow-situation-setup} let $X/B$ be good.
Let $\mathcal{E}$ be a finite locally free sheaf of
rank $r$ on $X$. Let $\mathcal{L}$ be an invertible
sheaf on $X$. Then we have
\begin{equation}
\label{equation-twist}
c_i({\mathcal E} \otimes {\mathcal L})
=
\sum\nolimits_{j = 0}^i
\binom{r - i + j}{j} c_{i - j}({\mathcal E}) c_1({\mathcal L})^j
\end{equation}
in $A^*(X)$.

\href{https://stacks.math.columbia.edu/tag/0E4Y}{\texttt{Stacks tag 0E4Y}}


Let $S$ be a scheme. Let $X$ be a locally Noetherian algebraic space over $S$.
Let $K$ be an object of $D_\QCoh(\mathcal{O}_X)$. The following are equivalent
\begin{enumerate}
\item For every \'etale morphism $U \to X$ where $U$ is a scheme
the restriction $K|_U$ is a dualizing complex for $U$ (as discussed above).
\item There exists a surjective \'etale morphism $U \to X$ where $U$ is a
scheme such that $K|_U$ is a dualizing complex for $U$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0E53}{\texttt{Stacks tag 0E53}}


Let $S$ be a scheme. Let $X$ be a locally Noetherian
quasi-separated algebraic space over $S$.
Let $\omega_X^\bullet$ be a dualizing complex on $X$. Then $X$ the function
$|X| \to \mathbf{Z}$ defined by
$$
x \longmapsto \delta(x)\text{ such that }
\omega_{X, \overline{x}}^\bullet[-\delta(x)]
\text{ is a normalized dualizing complex over }
\mathcal{O}_{X, \overline{x}}
$$
is a dimension function on $|X|$.

\href{https://stacks.math.columbia.edu/tag/0E55}{\texttt{Stacks tag 0E55}}


\begin{reference}
This is almost the same as \cite[Example 4.2]{Neeman-Grothendieck}.
\end{reference}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism between quasi-separated and quasi-compact
algebraic spaces over $S$. The functor $Rf_* : D_\QCoh(X) \to D_\QCoh(Y)$
has a right adjoint.

\href{https://stacks.math.columbia.edu/tag/0E5C}{\texttt{Stacks tag 0E5C}}


In diagram (\ref{equation-base-change}) the map
$a \circ Rg_* \leftarrow Rg'_* \circ a'$ is an isomorphism.

\href{https://stacks.math.columbia.edu/tag/0ARZ}{\texttt{Stacks tag 0ARZ}}


Let $R$ be a topological ring. Let $M$ be a linearly topologized
$R$-module. Let $N \subset M$ be a submodule. Then
\begin{enumerate}
\item $0 \to N^\wedge \to M^\wedge \to (M/N)^\wedge$ is exact, and
\item $N^\wedge$ is the closure of the image of $N \to M^\wedge$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0AS0}{\texttt{Stacks tag 0AS0}}


\begin{reference}
\cite[Theorem 8.1]{Ma}
\end{reference}
Let $R$ be a topological ring. Let $M$ be a linearly topologized
$R$-module. Let $N \subset M$ be a submodule. Assume $M$ has a
countable fundamental system of neighbourhoods of $0$. Then
\begin{enumerate}
\item $0 \to N^\wedge \to M^\wedge \to (M/N)^\wedge \to 0$ is exact,
\item $N^\wedge$ is the closure of the image of $N \to M^\wedge$,
\item $M^\wedge \to (M/N)^\wedge$ is open.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0AMV}{\texttt{Stacks tag 0AMV}}


Let $A$ be a linearly topologized ring.
\begin{enumerate}
\item An element $f \in A$ is called {\it topologically nilpotent}
if $f^n \to 0$ as $n \to \infty$.
\item A {\it weak ideal of definition} for $A$ is an open ideal
$I \subset A$ consisting entirely of topologically nilpotent elements.
\item We say $A$ is {\it weakly pre-admissible} if $A$ has a weak
ideal of definition.
\item We say $A$ is {\it weakly admissible} if $A$ is weakly pre-admissible
and complete\footnote{By our conventions this includes separated.}.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0DCZ}{\texttt{Stacks tag 0DCZ}}


Let $A$ be a weakly admissible topological ring. Let $I \subset A$
be a weak ideal of definition. Then $(A, I)$ is a henselian pair.

\href{https://stacks.math.columbia.edu/tag/0AMY}{\texttt{Stacks tag 0AMY}}


Let $\varphi : A \to B$ be a continuous map of weakly admissible topological
rings. The following are equivalent
\begin{enumerate}
\item $\varphi$ is taut,
\item for every weak ideal of definition $I \subset A$ the closure of
$\varphi(I)B$ is a weak ideal of definition of $B$ and these form a
fundamental system of weak ideals of definition of $B$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0GX2}{\texttt{Stacks tag 0GX2}}


Let $A$ be a linearly topologized ring. The map $A \to A^\wedge$
from $A$ to its completion is taut.

\href{https://stacks.math.columbia.edu/tag/0GBR}{\texttt{Stacks tag 0GBR}}


Let $A$ and $B$ be pre-adic topological rings. A ring homomorphism
$\varphi : A \to B$ is {\it adic}\footnote{This may be nonstandard terminology.}
if there exists an ideal of definition $I \subset A$ such that
the topology on $B$ is the $I$-adic topology.

\href{https://stacks.math.columbia.edu/tag/0GXC}{\texttt{Stacks tag 0GXC}}


Let $\varphi : A \to B$ be a continuous homomorphism between
pre-adic topological rings. If $\varphi$ is adic, then $\varphi$ is taut.

\href{https://stacks.math.columbia.edu/tag/0GXE}{\texttt{Stacks tag 0GXE}}


\begin{reference}
\cite[Definition 8.3.8]{Gabber-Ramero}
\end{reference}
Let $A$ be a linearly topologized ring.
\begin{enumerate}
\item We say $A$ is {\it weakly pre-adic}\footnote{In \cite{Gabber-Ramero} the
authors say $A$ is {\it $c$-adic}.} if there exists an ideal
$I \subset A$ such that the closure of $I^n$ is open for all $n \geq 0$
and these closures form a fundamental system of open ideals.
\item We say $A$ is {\it weakly adic} if $A$ is weakly pre-adic
and complete\footnote{By our conventions this includes separated.}.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0GXL}{\texttt{Stacks tag 0GXL}}


In the situation above, if $B$ has a countable fundamental system of
open ideals, then $A$ has a countable fundamental system of open ideals.

\href{https://stacks.math.columbia.edu/tag/0GXM}{\texttt{Stacks tag 0GXM}}


In the situation above, if $B$ is weakly pre-admissible, then
$A$ is weakly pre-admissible.

\href{https://stacks.math.columbia.edu/tag/0GXN}{\texttt{Stacks tag 0GXN}}


In the situation above, if $B$ is pre-admissible, then $A$
is pre-admissible.

\href{https://stacks.math.columbia.edu/tag/0GXP}{\texttt{Stacks tag 0GXP}}


In the situation above, if $B$ is weakly pre-adic, then $A$
is weakly pre-adic.

\href{https://stacks.math.columbia.edu/tag/0AI7}{\texttt{Stacks tag 0AI7}}


Let $S$ be a scheme. We say a sheaf $X$ on $(\Sch/S)_{fppf}$ is an
{\it affine formal algebraic space} if there exist
\begin{enumerate}
\item a directed set $\Lambda$,
\item a system $(X_\lambda, f_{\lambda \mu})$ over $\Lambda$
in $(\Sch/S)_{fppf}$ where
\begin{enumerate}
\item each $X_\lambda$ is affine,
\item each $f_{\lambda \mu} : X_\lambda \to X_\mu$ is a thickening,
\end{enumerate}
\end{enumerate}
such that
$$
X \cong \colim_{\lambda \in \Lambda} X_\lambda
$$
as fppf sheaves and $X$ satisfies a set theoretic condition
(see Remark \ref{formal-spaces-remark-set-theoretic}). A
{\it morphism of affine formal algebraic spaces}
over $S$ is a map of sheaves.

\href{https://stacks.math.columbia.edu/tag/0AIB}{\texttt{Stacks tag 0AIB}}


Let $S$ be a scheme. Let $X$ be a sheaf on $(\Sch/S)_{fppf}$.
Then $X$ is an affine formal algebraic space if and only if
the following hold
\begin{enumerate}
\item any morphism $U \to X$ where $U$ is an affine scheme over $S$
factors through a morphism $T \to X$ which is representable and a
thickening with $T$ an affine scheme over $S$, and
\item a set theoretic condition as in Remark \ref{formal-spaces-remark-set-theoretic}.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0AII}{\texttt{Stacks tag 0AII}}


Let $S$ be a scheme. Let $X$ be an affine formal algebraic space over $S$.
The following are equivalent
\begin{enumerate}
\item there exists a system $X_1 \to X_2 \to X_3 \to \ldots$
of thickenings of affine schemes over $S$ such that $X = \colim X_n$,
\item there exists a choice $X = \colim X_\lambda$ as in
Definition \ref{formal-spaces-definition-affine-formal-algebraic-space}
such that $\Lambda$ is countable.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0AIK}{\texttt{Stacks tag 0AIK}}


Let $X$ be an affine formal algebraic space over a scheme $S$.
\begin{enumerate}
\item If $X$ is Noetherian, then $X$ is adic*.
\item If $X$ is adic*, then $X$ is adic.
\item If $X$ is adic, then $X$ is weakly adic.
\item If $X$ is weakly adic, then $X$ is classical.
\item If $X$ is weakly adic, then $X$ is countably indexed.
\item If $X$ is countably indexed, then $X$ is McQuillan.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0AKM}{\texttt{Stacks tag 0AKM}}


Let $S$ be a scheme. Let $X$ be an affine formal algebraic space.
The following are equivalent
\begin{enumerate}
\item $X$ is Noetherian,
\item $X$ is adic* and for every closed immersion $T \to X$ with $T$ a scheme,
$T$ is Noetherian,
\item $X$ is adic* and for some choice of $X = \colim X_\lambda$ as in
Definition \ref{formal-spaces-definition-affine-formal-algebraic-space}
the schemes $X_\lambda$ are Noetherian, and
\item $X$ is weakly adic and for some choice $X = \colim X_\lambda$
as in Definition \ref{formal-spaces-definition-affine-formal-algebraic-space}
the schemes $X_\lambda$ are Noetherian.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0AIM}{\texttt{Stacks tag 0AIM}}


Let $S$ be a scheme. We say a sheaf $X$ on $(\Sch/S)_{fppf}$ is a
{\it formal algebraic space} if there exist a family of maps
$\{X_i \to X\}_{i \in I}$ of sheaves such that
\begin{enumerate}
\item $X_i$ is an affine formal algebraic space,
\item $X_i \to X$ is representable by algebraic spaces and \'etale,
\item $\coprod X_i \to X$ is surjective as a map of sheaves
\end{enumerate}
and $X$ satisfies a set theoretic condition
(see Remark \ref{formal-spaces-remark-set-theoretic}). A
{\it morphism of formal algebraic spaces}
over $S$ is a map of sheaves.

